function updateFX(dt){for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt;p.o.position.x+=p.vx*dt;p.o.position.y+=p.vy*dt;p.o.position.z+=p.vz*dt;p.vy-=5*dt;p.o.rotation.z+=p.spin*dt;p.o.scale.setScalar(Math.max(0,p.life/p.max));if(p.life<=0){p.o.removeFromParent();particles.splice(i,1)}}for(let i=mixers.length-1;i>=0;i--){const m=mixers[i];m.mix.update(dt);m.time-=dt;if(m.time<=0){if(m.remove)m.object.removeFromParent();m.mix.stopAllAction();mixers.splice(i,1)}}for(const c of captive){c.g.position.y=c.y+Math.sin(gameTime*3+c.x)*.1;c.g.rotation.z=gameTime;}toastTime-=dt;if(toastTime<=0)$('#toast').style.opacity=0;shake=Math.max(0,shake-dt*1.8);}
function updateUI(){if(!renderer)return;$('#score').textContent=String(score).padStart(6,'0');$('#best').textContent=String(Math.max(best,score)).padStart(6,'0');$('#stageLabel').textContent=`0${stage+1} / 04 · ${STAGES[stage].type}`;$('#stageName').textContent=STAGES[stage].name;$('#lives').textContent='● '.repeat(Math.max(0,lives));$('#chargePct').textContent=burst>0?'BURST!':Math.floor(charge)+'%';$('#chargeFill').style.width=(burst>0?burst/5*100:charge)+'%';$('#chargeButton').classList.toggle('ready',charge>=100);$('#comboValue').textContent='×'+(1+Math.floor(combo/8));$('#comboLabel').textContent=combo>=8?'INK CREDIBLE COMBO':wideTime>0?'WIDE PADDLE':slowTime>0?'SLOW MOTION':'MAKE YOUR MARK';const docked=balls.some(b=>b.docked);$('#playPrompt').style.display=(phase==='clear'||docked)&&phase!=='attract'?'block':'none';$('#promptMain').textContent=phase==='clear'?`NEXT: ${STAGES[Math.min(stage+1,3)].name}`:`${prompt('serve')} to serve`;$('#promptSub').textContent=phase==='clear'?`${prompt('serve')} · Keep the good angles coming`:STAGES[stage].tip;$('#devBadge').style.display=devUsed?'block':'none';}
function resize(){if(!renderer)return;const w=innerWidth,h=innerHeight;renderer.setSize(w,h);const aspect=w/h;let vh=28;if(aspect<.8)vh=22/aspect;const vw=vh*aspect;camera.left=-vw/2;camera.right=vw/2;camera.top=vh/2;camera.bottom=-vh/2;camera.updateProjectionMatrix();if(phase==='title'){boardGroup.position.set(aspect<.8?0:vw*.24,aspect<.8?8:0,0);boardGroup.rotation.z=aspect<.8?-.09:-.1;boardGroup.scale.setScalar(aspect<.8?.9:.88);}else{boardGroup.position.set(0,aspect<.8?.7:0,0);boardGroup.rotation.z=0;boardGroup.scale.setScalar(1);}titleGroup.visible=phase==='title';}

function prompt(action){const gp=lastInput==='gamepad',x=settings.glyphs==='xbox';return action==='serve'?(gp?(x?'A':'✕'):lastInput==='touch'?'Tap':'Space'):action==='burst'?(gp?(x?'Y':'△'):lastInput==='touch'?'Tap burst':'Shift'):gp?'Options':'Esc';}
function setPrompts(){$$('[data-prompt]').forEach(e=>e.textContent=prompt(e.dataset.prompt));if(phase==='title')$('#footerLeft').textContent=lastInput==='gamepad'?`${settings.glyphs==='xbox'?'A':'✕'} Select · ${settings.glyphs==='xbox'?'B':'○'} Back · Left stick / D-pad Move`:'Move: mouse / ← → · Serve: Space · Burst: Shift';updateUI();}
function focusButtons(){return $$(menuName?'#panel button:not(:disabled),#panel input,#panel select':'#title button:not(:disabled)');}
function focusMenu(i){const list=focusButtons();if(!list.length)return;menuFocus=(i+list.length)%list.length;$$('.focused').forEach(e=>e.classList.remove('focused'));list[menuFocus].classList.add('focused');list[menuFocus].focus({preventScroll:true});list[menuFocus].scrollIntoView({block:'nearest'});}
function showPanel(name,html){menuName=name;$('#panel').innerHTML=html;$('#overlay').style.display='flex';menuFocus=0;$$('.focused').forEach(e=>e.classList.remove('focused'));if(lastInput==='gamepad'||lastInput==='keyboard')focusMenu(0);}
function hideOverlay(){menuName='';$('#overlay').style.display='none';$('#panel').innerHTML='';}
function backButton(action='back'){return `<button class="back" data-action="${action}">${lastInput==='gamepad'?(settings.glyphs==='xbox'?'B':'○'):'Esc'} Back</button>`;}
function pause(){if(phase!=='playing'&&phase!=='clear')return;returnMenu=phase;if(netMode==='guest'&&online.connected){showPanel('pause',`<div class="eyebrow">YOUR CORNER OF THE PRINT SHOP</div><h2>Take a little space.</h2><p>The host keeps the ball rolling while you’re here.</p><div class="actions"><button class="primary" data-action="resume">Keep bouncing</button><button class="secondary" data-action="settings">Settings</button><button class="secondary" data-action="how">How to play</button>${online.isHub?'':'<button class="secondary" data-action="title">Leave room</button>'}</div>`);return;}phase='paused';showPause();}
function showPause(){showPanel('pause',`<div class="eyebrow">TAKE A BREATHER</div><h2>Hold that thought.</h2><p>Even a good bounce needs a little space.</p><div class="actions"><button class="primary" data-action="resume">Keep bouncing <span data-prompt="serve">${prompt('serve')}</span></button><button class="secondary" data-action="settings">Settings</button><button class="secondary" data-action="dev">Developer tools</button><button class="secondary" data-action="how">How to play</button><button class="secondary" data-action="about">About & credits</button>${online.isHub?'':'<button class="secondary" data-action="title">Back to title</button>'}</div>`);}
function resume(){if(netMode==='guest'&&online.connected){hideOverlay();return;}if(phase!=='paused')return;phase=returnMenu==='clear'?'clear':'playing';hideOverlay();}
function back(){audio.play('cancel');if(menuName==='pause')resume();else if(phase==='paused')showPause();else if(netMode==='guest'&&online.connected&&menuName)pause();else if(menuName==='online'&&online.active&&!online.connected){online.leave();netMode='solo';hideOverlay();}else if(menuName)hideOverlay();else if(phase==='playing'||phase==='clear')pause();}
function showSettings(){showPanel('settings',`${backButton()}<div class="eyebrow">MAKE YOURSELF AT HOME</div><h2>Your kind of bounce.</h2><div class="setting"><label for="musicVol">Music<small>A little groove goes a long way.</small></label><div class="sliderpack"><input id="musicVol" type="range" min="0" max="100" value="${Math.round(settings.music*100)}" data-setting="music" aria-label="Music volume"><output>${Math.round(settings.music*100)}%</output></div></div><div class="setting"><label for="sfxVol">Effects & voices</label><div class="sliderpack"><input id="sfxVol" type="range" min="0" max="100" value="${Math.round(settings.sfx*100)}" data-setting="sfx" aria-label="Effects volume"><output>${Math.round(settings.sfx*100)}%</output></div></div><div class="setting"><label for="glyphs">Controller symbols</label><select id="glyphs" data-setting="glyphs"><option value="ps" ${settings.glyphs==='ps'?'selected':''}>PlayStation · ✕ ○ □ △</option><option value="xbox" ${settings.glyphs==='xbox'?'selected':''}>Xbox · A B X Y</option></select></div><div class="setting"><label for="shake">Screen shake<small>Keep the ink from rattling.</small></label><input type="checkbox" id="shake" data-setting="shake" ${settings.shake?'checked':''}></div><div class="setting"><label for="assist">Touch auto-paddle<small>Follow the ball on touch devices.</small></label><input type="checkbox" id="assist" data-setting="assist" ${settings.assist?'checked':''}></div><p class="tiny">Settings are saved on this device. Touch: drag anywhere to move, tap to serve. A second finger unleashes a full burst.</p>`);}
function howTo(){showPanel('how',`${backButton()}<div class="eyebrow">THE ART OF A GOOD RETURN</div><h2>Small paddle. Big ideas.</h2><div class="hintrow"><span class="key">${lastInput==='gamepad'?'L / D-pad':'← → / A D'}</span><p>Move. The middle sends a straight shot. The edges cut a sharper angle.</p></div><div class="hintrow"><span class="key">${prompt('serve')}</span><p>Serve a ball, or begin the next stage. Mouse click and touch tap also serve.</p></div><div class="hintrow"><span class="key">${prompt('burst')}</span><p>At 100% charge, unleash 5 seconds of piercing ink. Break through whole rows.</p></div><div class="hintrow"><span class="key">${prompt('pause')}</span><p>Pause, change settings, or open the developer tools.</p></div><div class="tiles" style="margin-top:20px"><div class="tile"><b>Catch the good stuff</b>↔ Wide paddle · ×3 Multiball · ~ Slow ball.<br>Three spare balls. Clear four stages to win.</div><div class="tile"><b>Better together</b>Couch: P1 A/D, P2 arrows, or two pads.<br>Online: host a room and share its code. Both paddles share score and lives.</div></div><p class="tiny">Gold pockets hold extra balls. Double adds an upper paddle. Progressive steps the wall toward you. Lose a life only when every active ball is gone.</p>`);}
function slider(name,label,min,max,step=1,help=''){return `<div class="setting"><label for="dev-${name}">${label}${help?`<small>${help}</small>`:''}</label><div class="sliderpack"><input id="dev-${name}" data-dev="${name}" type="range" min="${min}" max="${max}" step="${step}" value="${cfg[name]}"><output>${cfg[name]}</output></div></div>`;}
function showDev(){devUsed=true;showPanel('dev',`${backButton('pausemenu')}<div class="eyebrow">THE PRINT SHOP / LIVE TUNING</div><h2>Make a little trouble.</h2>${slider('speed','Ball speed',8,20,.5)}${slider('paddleWidth','Paddle width',1.8,4.8,.1)}${slider('chargeRate','Charge gain',.5,3,.25)}<div class="setting"><label for="dev-god">Infinite spare balls</label><input id="dev-god" type="checkbox" data-dev="god" ${cfg.god?'checked':''}></div><div class="setting"><label for="dev-auto">AI paddle<small>Plays and advances stages automatically.</small></label><input id="dev-auto" type="checkbox" data-dev="auto" ${cfg.auto?'checked':''}></div><div class="tiles"><button class="secondary" data-action="devcharge">Fill burst</button><button class="secondary" data-action="devmulti">Multiball</button><button class="secondary" data-action="devnext">Next stage</button><button class="secondary" data-action="devreset">Reset defaults</button></div><p class="tiny">Tuning applies on resume. Developer tools mark this run. Settings reset at page reload. Network hosts control the simulation.</p>`);}
const aboutTabs=[['origin','Origin'],['craft','Craft'],['testing','Testing'],['engine','Engine'],['prompt','Prompt']];let aboutTab='origin';
import credits from './credits.json';
function showAbout(tab='origin'){aboutTab=tab;const s=credits.sourceInformation;let content='';if(tab==='origin'||tab==='craft'){const fields=tab==='origin'?['date','source','plan','genre','perspective','research','environment','model','usage']:['tech','artDirection','animation','audio','online','testing'];content=`<p>${tab==='origin'?'A playful, independent tribute to the paddle-and-wall rhythm of Super Breakout (1981). All art is built from geometry and ink.':'Built for the big screen, from a small sheet of paper.'}</p><dl class="metadata">${fields.map(k=>`<dt>${k.replace(/([A-Z])/g,' $1').replace(/^./,x=>x.toUpperCase())}</dt><dd>${s[k]}</dd>`).join('')}</dl>`;}else{const questions=tab==='testing'?['Issues caught','Critical issues','Most helpful test','Least helpful test']:tab==='engine'?['Best part','Wrong guesses','Built by hand','Hardest part','Engine changes','One wish']:['Best part','Confusing','Hardest part','One change'];const answers=credits[tab==='testing'?'testingFeedback':tab==='engine'?'engineFeedback':'promptFeedback'];content=`<div class="feedback">${answers.map((a,i)=>`<h3>${questions[i]}</h3><p>${a}</p>`).join('')}</div>`;}
 showPanel('about',`${backButton()}<div class="eyebrow">${tab==='testing'?'TESTING FEEDBACK':tab==='engine'?'ENGINE FEEDBACK':tab==='prompt'?'PROMPT FEEDBACK':'SOURCE INFORMATION'}</div><h2>Behind the bounce.</h2><div class="minorlinks" style="margin:0 0 20px">${aboutTabs.map(([key,label])=>`<button class="textbutton" data-about="${key}" style="${tab===key?'color:var(--orange);border-bottom-color:var(--orange)':''}">${label}</button>`).join('')}</div>${content}`);}
function showOnline(){showPanel('online',`${backButton()}<div class="eyebrow">ONE WALL. TWO PADDLES.</div><h2>Make a connection.</h2><p>Host a room, then share its six-letter code with a friend. Your score, spare balls and glorious mistakes are shared.</p><div class="actions"><button class="primary" data-action="host">Host a room <span>↗</span></button></div><div class="setting"><label for="joinCode">Or join a friend</label><input id="joinCode" type="text" maxlength="6" autocomplete="off" spellcheck="false" placeholder="ROOM CODE" aria-label="Room code" style="text-transform:uppercase;letter-spacing:3px;width:180px"></div><div class="actions"><button class="secondary" data-action="join">Join room</button></div><div id="roomDisplay">${online.role==='host'&&online.roomCode?`<div class="roomcode">${online.roomCode}</div><button class="textbutton" data-action="copycode">Copy room code</button>`:''}</div><p id="networkStatus" class="networkstatus">Cross-device play uses a WebRTC peer connection. Keep the host’s game open.</p><p class="tiny">Same-device tabs also work. The room starts when your partner connects.</p>`);}
async function hostRoom(){if($('#networkStatus'))$('#networkStatus').textContent='Opening the ink line…';try{const code=await online.host();if($('#roomDisplay'))$('#roomDisplay').innerHTML=`<div class="roomcode">${code}</div><button class="textbutton" data-action="copycode">Copy room code</button>`;}catch(e){if($('#networkStatus'))$('#networkStatus').textContent=e.message;}}
async function joinRoom(){const code=$('#joinCode')?.value?.trim();if(!code)return;if($('#networkStatus'))$('#networkStatus').textContent='Finding your partner…';try{await online.join(code);}catch(e){if($('#networkStatus'))$('#networkStatus').textContent=e.message;}}
function setSetting(key,value){settings[key]=value;if(key==='music')audio.setMusicVolume(value);if(key==='sfx')audio.setSfxVolume(value);saveSettings();setPrompts();}
function handleAction(a){if(hubEnded)return;if(online.isHub&&['start','coop','online','again','title'].includes(a))return;audio.unlock();audio.play('menu');switch(a){case'start':if(online.active)online.leave();startRun();break;case'coop':if(online.active)online.leave();startRun('coop');break;case'online':showOnline();break;case'host':hostRoom();break;case'join':joinRoom();break;case'copycode':navigator.clipboard?.writeText(online.roomCode).then(()=>toast('ROOM CODE COPIED')).catch(()=>toast(online.roomCode));break;case'settings':showSettings();break;case'how':howTo();break;case'about':showAbout();break;case'back':back();break;case'pausemenu':showPause();break;case'resume':resume();break;case'dev':showDev();break;case'title':showTitle();break;case'again':if(online.active){startRun('online')}else startRun(mode==='coop'?'coop':'solo');break;case'devcharge':charge=100;toast('BURST FILLED');break;case'devmulti':takePower('multi');break;case'devnext':if(stage<3)loadStage(stage+1);else{hideOverlay();finishRun(true)}break;case'devreset':Object.assign(cfg,DEFAULTS);showDev();toast('DEFAULTS RESTORED');break;}}
function userActivity(kind){if(hubEnded)return true;idleAt=performance.now();if(kind&&kind!==lastInput){lastInput=kind;setPrompts();}if(phase==='attract'){const keep=attractMenu==='online'&&online.active&&!online.connected;showTitle(keep);if(keep)showOnline();return true}return false;}
function sendAction(action){const p=paddles.find(p=>p.seat===1)||paddles[0];online.sendInput({x:p?.x||0,[action]:true});}
function pointerWorld(event){const v=new THREE.Vector3(event.clientX/innerWidth*2-1,-event.clientY/innerHeight*2+1,0);v.unproject(camera);v.sub(boardGroup.position);return v.x;}
function getPads(){try{return [...navigator.getGamepads()].filter(Boolean)}catch{return[]}}
function pollPads(dt){if(hubEnded||online.server)return;const pads=getPads();let active=false;for(let index=0;index<pads.length;index++){const p=pads[index],prev=padPrevious[index]||[];const pressed=i=>!!p.buttons?.[i]?.pressed;const down=i=>pressed(i)&&!prev[i];const ax=p.axes?.[0]||0,ay=p.axes?.[1]||0;if(Math.abs(ax)>.18||Math.abs(ay)>.18||p.buttons.some(b=>b.pressed)){active=true;if(userActivity('gamepad')){padPrevious[index]=p.buttons.map(b=>b.pressed);continue;}}
 if(index===0){if(down(9)&&!pressed(8)){if(menuName)back();else pause();}if(menuName||phase==='title'){menuRepeat-=dt;const up=pressed(12)||ay<-.5,downDir=pressed(13)||ay>.5;if((up||downDir)&&menuRepeat<=0){focusMenu(menuFocus+(up?-1:1));audio.play('menu');menuRepeat=.2;}if(!up&&!downDir)menuRepeat=0;const focused=focusButtons()[menuFocus];if(focused?.matches('input[type=range]')&&(pressed(14)||pressed(15)||Math.abs(ax)>.5)&&menuRepeat<=0){const sign=pressed(14)||ax<-.5?-1:1;focused.value=clamp(+focused.value+sign*Number(focused.step||1),+focused.min,+focused.max);focused.dispatchEvent(new Event('input',{bubbles:true}));menuRepeat=.15;}if(focused?.tagName==='SELECT'&&(down(14)||down(15))){focused.selectedIndex=1-focused.selectedIndex;focused.dispatchEvent(new Event('change',{bubbles:true}));}if(down(0)){if(focused?.matches('input[type=checkbox]')){focused.checked=!focused.checked;focused.dispatchEvent(new Event('change',{bubbles:true}));}else focused?.click();}if(down(1))back();}else{if(down(0))serve();if(down(3))activateBurst();}}
 else if(!menuName){if(down(0))serve();if(down(3))activateBurst();}
 padPrevious[index]=p.buttons.map(b=>b.pressed);}
 if(active)setPrompts();}
function setupInput(){document.addEventListener('pointerdown',e=>{if(userActivity(e.pointerType==='touch'?'touch':'mouse')){e.preventDefault();e.stopImmediatePropagation();return;}audio.unlock();},{capture:true});document.addEventListener('pointermove',e=>{if(menuName||phase==='title')userActivity(e.pointerType==='touch'?'touch':'mouse');});document.addEventListener('click',e=>{const about=e.target.closest('[data-about]');if(about){showAbout(about.dataset.about);return}const b=e.target.closest('[data-action]');if(b)handleAction(b.dataset.action);});document.addEventListener('pointerover',e=>{const b=e.target.closest('button,input,select');if(b){const i=focusButtons().indexOf(b);if(i>=0){menuFocus=i;$$('.focused').forEach(x=>x.classList.remove('focused'));b.classList.add('focused');}}});
 for(const type of ['input','change'])document.addEventListener(type,e=>{const el=e.target;if(el.dataset.setting){const key=el.dataset.setting;let value=el.type==='checkbox'?el.checked:el.type==='range'?+el.value/100:el.value;setSetting(key,value);if(el.nextElementSibling?.tagName==='OUTPUT')el.nextElementSibling.textContent=Math.round(value*100)+'%';}if(el.dataset.dev){const key=el.dataset.dev;cfg[key]=el.type==='checkbox'?el.checked:+el.value;if(el.nextElementSibling?.tagName==='OUTPUT')el.nextElementSibling.textContent=cfg[key];}});
 document.addEventListener('keydown',e=>{if(e.target.matches('input[type=text]')){if(e.code==='Enter')joinRoom();if(e.code!=='Escape')return;}if(userActivity('keyboard'))return;audio.unlock();keys.add(e.code);if(['Space','ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Tab'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='Escape'||e.code==='KeyP'){if(menuName)back();else pause();return;}if(menuName||phase==='title'){if(e.code==='ArrowDown'||e.code==='Tab')focusMenu(menuFocus+1);else if(e.code==='ArrowUp')focusMenu(menuFocus-1);else if(e.code==='Enter'||e.code==='Space'){const f=focusButtons()[menuFocus];if(f?.type==='checkbox'){f.checked=!f.checked;f.dispatchEvent(new Event('change',{bubbles:true}));}else f?.click();}else if((e.code==='ArrowLeft'||e.code==='ArrowRight')&&document.activeElement?.type==='range'){const el=document.activeElement;el.value=+el.value+(e.code==='ArrowLeft'?-1:1)*Number(el.step||1);el.dispatchEvent(new Event('input',{bubbles:true}));}return;}if(e.code==='Space'||e.code==='Enter')serve();if(e.code==='ShiftLeft'||e.code==='ShiftRight')activateBurst();});
 document.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{keys.clear();if(phase==='playing'&&!online.active)pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&phase==='playing'&&!online.active)pause();});
 let touchCount=0;renderer.domElement.addEventListener('pointerdown',e=>{const touch=e.pointerType==='touch';if(userActivity(touch?'touch':'mouse'))return;audio.unlock();pointerX=pointerWorld(e);pointerActive=true;if(touch){touchCount++;renderer.domElement.setPointerCapture(e.pointerId);if(touchCount>=2)activateBurst();else serve();}else if(e.button===2)activateBurst();else serve();});renderer.domElement.addEventListener('pointermove',e=>{const touch=e.pointerType==='touch';if(!touch&&userActivity('mouse'))return;if(touch&&e.buttons===0)return;pointerX=pointerWorld(e);pointerActive=true;});renderer.domElement.addEventListener('pointerup',e=>{if(e.pointerType==='touch')touchCount=Math.max(0,touchCount-1);});renderer.domElement.addEventListener('contextmenu',e=>e.preventDefault());$('#menuButton').onclick=()=>{userActivity(lastInput);pause();};$('#chargeButton').onclick=()=>{audio.unlock();activateBurst();};window.addEventListener('resize',resize);
}
function startAttract(){attractMenu=menuName;hideOverlay();startRun('solo');phase='attract';loadStage(0);$('#title').style.display='none';$('#hud').style.display='block';$('#attract').style.display='block';$('#menuButton').style.display='none';$('#playPrompt').style.display='none';$('#footerLeft').textContent='AI AT THE PADDLE · FOUR WAYS TO MAKE A BREAK';resize();}
function snapshot(){return {phase,mode,stage,score,lives,charge,combo,burst,wideTime,slowTime,elapsed,balls:balls.length,remaining:bricks.filter(b=>b.alive).length,renderer:renderer?.backend?.isWebGPUBackend?'WebGPU':'WebGL2 fallback',physics:'Rapier 0.19.3',three:'180',stats:{...stats},settings:{...settings},config:{...cfg},ballState:balls.map(b=>({x:b.body.translation().x,y:b.body.translation().y,vx:b.body.linvel().x,vy:b.body.linvel().y,docked:b.docked})),paddles:paddles.map(p=>({x:p.x,y:p.y,seat:p.seat,width:p.width})),metrics:{...metrics}};}
function networkState(){const s=snapshot();return {...s,runID,captive:captive.map(c=>({x:c.x,y:c.y})),bricks:bricks.filter(b=>b.alive).map(b=>({id:b.id,hp:b.hp,y:b.y})),ballList:balls.map(b=>({id:b.id,x:b.body.translation().x,y:b.body.translation().y})),powerups:powerups.map(p=>({x:p.x,y:p.y,type:p.type}))};}
function applyNet(s){if(!renderer||!s||online.role!=='guest')return;if(netBuild!==s.stage||netRunID!==s.runID||!paddles.length){mode='online';loadStage(s.stage);netBuild=s.stage;netRunID=s.runID;hideOverlay();}const oldPhase=phase;phase=s.phase;score=s.score;lives=s.lives;stage=s.stage;charge=s.charge;combo=s.combo;burst=s.burst;stats=s.stats||stats;wideTime=s.wideTime;slowTime=s.slowTime;const activeBricks=new Map((s.bricks||[]).map(b=>[b.id,b]));for(const b of bricks){const n=activeBricks.get(b.id);if(!n&&b.alive){b.alive=false;burstParticles(b.x,b.y,b.c,5);b.group.removeFromParent();}if(n){if(!b.alive){b.alive=true;playGroup.add(b.group);}b.group.visible=true;b.hp=n.hp;b.y=n.y;b.group.position.y=n.y;}}
 for(const cp of captive)playGroup.remove(cp.g);captive=[];for(const cp of s.captive||[]){const g=ballMesh(C.yellow,.25);g.position.set(cp.x,cp.y,.4);playGroup.add(g);captive.push({x:cp.x,y:cp.y,g});}for(const p of powerups)playGroup.remove(p.g);powerups=[];for(const p of s.powerups||[])dropPower(p.x,p.y,p.type);
 for(const b of balls){playGroup.remove(b.group);b.trail.forEach(t=>playGroup.remove(t));}balls=[];for(const b of s.ballList||[]){const o=ballMesh(burst>0?C.coral:C.paper,.2);o.position.set(b.x,b.y,.4);playGroup.add(o);balls.push({group:o,body:{translation:()=>({x:b.x,y:b.y}),linvel:()=>({x:0,y:0})},docked:false,trail:[]});}
 s.paddles?.forEach((p,i)=>{if(paddles[i]){if(p.seat!==online.mySeat){paddles[i].x=p.x;paddles[i].group.position.x=p.x;}paddles[i].width=p.width;paddles[i].group.scale.x=p.width/3.1;}});if(['gameover','victory'].includes(phase)&&oldPhase!==phase)showEnd(phase==='victory');if(oldPhase==='paused'&&phase==='playing'&&menuName==='netpause')hideOverlay();if(phase==='paused'&&!menuName)showPanel('netpause','<div class="eyebrow">A MOMENT OF STILLNESS</div><h2>Host has paused.</h2><p>Your partner will be right back.</p>');updateUI();}
function updateGuest(dt){if(hubEnded)return;const p=paddles.find(p=>p.seat===online.mySeat)||paddles[1];if(!p)return;if(menuName){online.sendInput({x:p.x});return;}const pad=getPads()[0];let tx=p.x;if(pointerActive)tx=pointerX;if(keys.has('KeyA')||keys.has('ArrowLeft'))tx-=20*dt;if(keys.has('KeyD')||keys.has('ArrowRight'))tx+=20*dt;const axis=(pad?.axes?.[0]||0)+(pad?.buttons?.[14]?.pressed?-1:0)+(pad?.buttons?.[15]?.pressed?1:0);if(Math.abs(axis)>.12)tx+=axis*21*dt;p.x=clamp(tx,-9+p.width/2,9-p.width/2);p.group.position.x=p.x;online.sendInput({x:p.x});}
function frame(t){const dt=Math.min((t-lastTime)/1000||.016,.06);lastTime=t;metrics.frames++;pollPads(dt);if(phase==='title'&&performance.now()-idleAt>=10000)startAttract();if(netMode==='guest'&&online.connected){updateGuest(dt);}else{accumulator+=dt;if(!['playing','attract','clear'].includes(phase)||(online.isHub&&online.time()<0))accumulator=0;while(accumulator>=1/120){simulate(1/120);accumulator-=1/120;}}
 if(mode==='online'&&netMode==='host'&&online.connected)online.sendState(networkState());updateFX(dt);audio.update(dt,['playing','attract','title'].includes(phase));if(settings.shake&&shake>0){camera.position.x=Math.sin(t*.13)*shake*.3;camera.position.y=-3.8+Math.cos(t*.1)*shake*.3;}else{camera.position.x=0;camera.position.y=-3.8;}if(phase==='title'){boardGroup.rotation.z=-.1+Math.sin(t*.0004)*.012;titleGroup.rotation.z=Math.sin(t*.00008)*.025;}updateUI();renderer.render(scene,camera);requestAnimationFrame(frame);}
async function init(){try{
 $('#loadtext').textContent='MIXING THE PHYSICS…';await RAPIER.init();renderer=new THREE.WebGPURenderer({antialias:true,alpha:false,forceWebGL:new URLSearchParams(location.search).has('webgl')});renderer.setPixelRatio(Math.min(devicePixelRatio,2));await renderer.init();renderer.outputColorSpace=THREE.SRGBColorSpace;$('#game').appendChild(renderer.domElement);$('#engineTag').textContent=renderer.backend.isWebGPUBackend?'WEBGPU ARCADE':'WEBGL2 ARCADE';buildScene();disposeWorld();loadStage(0);if(navigator.maxTouchPoints>0)lastInput='touch';setupInput();setPrompts();$('#loading').style.display='none';
 window.__BOUNCEOUT__={ready:true,state:snapshot,start:startRun,step(seconds){for(let i=0;i<Math.min(seconds,120)*120;i++){simulate(1/120);updateFX(1/120)}updateUI();return snapshot();},setAuto(v){cfg.auto=v;},clearStage(){for(const b of bricks)if(b.alive){b.hp=1;hitBrick(b,null);colliders.delete(b.collider.handle);world.removeRigidBody(b.body);}stageComplete();},loseBall:()=>loseBall(true),pause,resume,setSetting,dev(v){Object.assign(cfg,v);devUsed=true;},spawnPower(type){const p=paddles[0];dropPower(p.x,p.y+.6,type);},launch:serve,idle(seconds){idleAt=performance.now()-seconds*1000;},audio:()=>audio.metrics,online,showTitle,showAbout,async audioTest(){const ctx=new OfflineAudioContext(2,48000,48000);const a=new ArcadeAudio({context:ctx});const promise=ctx.startRendering();a.update(.016,true);for(const n of ['brick','paddle','wall','launch','powerup','lose','win','charge','burst','menu','confirm','cancel','stage'])a.play(n);a.speak('ready');const b=await promise;const data=b.getChannelData(0);let peak=0,ss=0;for(const x of data){peak=Math.max(peak,Math.abs(x));ss+=x*x;}return {peak,rms:Math.sqrt(ss/data.length),metrics:a.metrics};}};
 if(online.isHub){phase='waiting';$('#title').style.display='none';$('#boardCaption').style.display='none';resize();await online.init();await online.ready();}requestAnimationFrame(frame);
 }catch(e){console.error(e);$('#loadtext').textContent='THE INK DIDN’T QUITE DRY.';$('#error').style.display='block';$('#error').textContent=e.message+' · Try a current browser with WebGPU or WebGL2 enabled.';window.__BOUNCEOUT_ERROR__=String(e);if(online.isHub)window.AIHub.fail(e.message);}}
